// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the from address, single recipient encoded via address param, and value
    // We use an adversarial callee that can be toggled to revert its transferFrom to exercise the difference
    function testFuzz_property(address from, uint256 v, bool shouldRevert) public {
        // keep tos non-zero length by using a single derived address (fuzzer supplies 'from' and v and shouldRevert)
        vm.assume(from != address(0)); // keep from sensible

        // deploy a helper that implements transferFrom and can revert on demand
        ReverterOrRecorder helper = new ReverterOrRecorder();
        helper.setShouldRevert(shouldRevert);

        address[] memory tos = new address[](1);
        // put some recipient (use the test contract's address derived from fuzz input to vary)
        tos[0] = address(uint160(uint256(keccak256(abi.encodePacked(from, v)))));

        // Call transfer and observe whether it returns or reverts.
        bool ok;
        try c.transfer(from, address(helper), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE (checked here): Reference C requires that WHEN any callee call fails, transfer MUST NOT return true.
        // We observe the behavior by controlling the callee: if it reverts (shouldRevert==true), the reference C will revert
        // (so ok==false) for ALL inputs. The mutant (which ignores the return) can return true while the callee failed.
        // Therefore assert that when shouldRevert is true, the call did NOT succeed.
        assertTrue(!shouldRevert ? true : (ok == false));
    }
}

// Adversarial helper that either reverts on transferFrom or records the call details.
contract ReverterOrRecorder {
    bool public shouldRevert;
    // records
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;
    uint256 public calledCount;

    function setShouldRevert(bool r) public {
        shouldRevert = r;
    }

    // match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        if (shouldRevert) revert("forced revert");
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        calledCount += 1;
        return true;
    }
}
